def nearest_levels(book, prices):
    answers = []
    for p in prices:
        node, best = book, None
        while node is not None:
            level, left, right = node
            if best is None or (abs(level - p), level) < (abs(best - p), best):
                best = level
            if p == level:
                break
            node = left if p < level else right
        answers.append(best)
    return answers
